import fs from 'fs';

const h = fs.readFileSync('tools/casamomo_book_page.html', 'utf8');

console.log('Total length:', h.length);

// Check if calendar is inline HTML or generated by JS
const calIdx = h.indexOf('November 2026') !== -1 ? h.indexOf('November 2026') : h.indexOf('November');
console.log('November index:', calIdx);

// Check all script tags
const scripts = [...h.matchAll(/<script[^>]*src="([^"]*)"/g)].map(m => m[1]);
console.log('External scripts:', scripts.length);

// Check inline scripts
const inlineScripts = [...h.matchAll(/<script(?![^>]*src)[^>]*>([\s\S]*?)<\/script>/g)].map(m => m[1].slice(0, 100));
console.log('Inline scripts count:', inlineScripts.length);
